function sbFill(d, data) {
            if (!data) return;

            /* scannable Code 128 barcode of the full location code (e.g. MUS-1-4-3-1) */
            try { const hero = d.querySelector('.location-hero'), old = d.getElementById('sbBarcode'); if (old) old.remove();
              if (hero && data.Location_Code) { hero.style.position = 'relative'; hero.style.paddingRight = '80mm'; const cd = d.getElementById('locationCode'); if (cd) { cd.style.fontSize = (data.Location_Code.length > 12 ? '17mm' : '21mm'); cd.style.whiteSpace = 'nowrap'; } const bc = d.createElement('div'); bc.id = 'sbBarcode';
                bc.style.cssText = 'position:absolute;right:4mm;top:50%;transform:translateY(-50%);width:72mm;background:#fff;padding:1.5mm 2.5mm 1mm;border:1px solid #d4d4d4;border-radius:2mm;text-align:center;line-height:1';
                bc.innerHTML = '<div style="height:15mm">' + rkBarSvg(data.Location_Code, '100%') + '</div><div style="font:600 2.8mm/1.3 Consolas,monospace;letter-spacing:.6mm;color:#2c3e50;margin-top:.8mm">' + plEsc(data.Location_Code) + '</div>'; hero.appendChild(bc); } } catch (e) {}

            const parts = data.Location_Code.split('-');
            // For "MAQ-3-2-1-4" → parts = ["MAQ", "3", "2", "1", "4"]
            const zone = parts[0] || '';
            const aisle = parts[1] || '';
            const bay = parts[2] || '';
            const level = parts[3] || '';  // This is the 4th part (Level)
            const rack = parts[4] || '';    // This would be the 5th part if it exists

            // ─── LOCATION CODE - Shows ALL 4 parts ───
            // If there are 5 parts (Zone-Aisle-Bay-Level-Rack), show all 5
            // If there are 4 parts (Zone-Aisle-Bay-Level), show all 4
            let codeHtml = `${zone}`;
            for (let i = 1; i < parts.length; i++) {
                codeHtml += `-<span class="highlight">${parts[i]}</span>`;
            }
            d.getElementById('locationCode').innerHTML = codeHtml;

            // Header
            d.getElementById('whsName').textContent = zone;
            d.getElementById('deptName').textContent = data.Dept_Desc.toUpperCase();
            d.getElementById('locationCodeDisplay').textContent = data.Location_Code;

            // 4-Column Grid
            d.getElementById('deptValue').textContent = data.Dept_Desc.toUpperCase();
            d.getElementById('rackingValue').textContent = data.Racking_Type.toUpperCase();
            d.getElementById('storageValue').textContent = data.Storage_Type.toUpperCase();
            d.getElementById('tempValue').textContent = data.Storage_Temp_Type.toUpperCase();

            // Store Description
            d.getElementById('storeDesc').textContent = data.Store_Desc;
            d.getElementById('storeTypeBadge').textContent = `🧃 ${data.Dept_Desc}`;

            // Condition Bar
            d.getElementById('miniTemp').textContent = data.STR_Mini_Temp + '°C';
            d.getElementById('miniHumidity').textContent = '65.00%';
            d.getElementById('capacity').textContent = data.Store_Capacity + ' UNITS';
            d.getElementById('regionId').textContent = data.Region_ID;

            // Map
            const mapImage = d.getElementById('mapImage');
            const svgMap = d.getElementById('svgMap');
            const mapPlaceholder = d.getElementById('mapPlaceholder');
            const mapFilename = d.getElementById('mapFilename');

            if (data.Map_Image && data.Map_Image.trim() !== '') {
                mapImage.src = data.Map_Image;
                mapImage.style.display = 'block';
                svgMap.style.display = 'none';
                mapPlaceholder.style.display = 'none';

                mapImage.onload = function() {
                    mapImage.style.display = 'block';
                    svgMap.style.display = 'none';
                    mapPlaceholder.style.display = 'none';
                };

                mapImage.onerror = function() {
                    mapImage.style.display = 'none';
                    svgMap.style.display = 'none';
                    mapPlaceholder.style.display = 'block';
                    mapFilename.textContent = `📁 ${data.Map_Image}`;
                };
            } else {
                mapImage.style.display = 'none';
                svgMap.style.display = 'block';
                mapPlaceholder.style.display = 'none';
            }

            d.getElementById('mapCoords').textContent = data.Location_Code;

            // Details Panel
            d.getElementById('detailZone').textContent = zone;
            d.getElementById('detailAisle').textContent = aisle;
            d.getElementById('detailBay').textContent = bay;
            d.getElementById('detailLevel').textContent = level;
            d.getElementById('detailRack').textContent = `${data.Racking_Type} ${bay}`;
            d.getElementById('detailDept').textContent = data.Dept_Desc;
            d.getElementById('detailStorage').textContent = data.Storage_Type;
            d.getElementById('detailTemp').textContent = data.STR_Mini_Temp + '°C';
            d.getElementById('detailHumidity').textContent = '65.00%';

            // 3-Column Grid
            d.getElementById('whsIdDisplay').textContent = data.WHs_ID;
            d.getElementById('regionIdDisplay').textContent = data.Region_ID;
            d.getElementById('storeTypeDisplay').textContent = data.Dept_Desc;

            // Footer
            d.getElementById('footerCode').textContent = data.Location_Code;
            d.getElementById('footerDesc').textContent = `${data.Dept_Desc} ${data.Storage_Type} ${data.Racking_Type}`;
            d.getElementById('footerRegion').textContent = data.Region_ID;

            // Date
            const now = new Date();
            const dateStr = now.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' });
            d.getElementById('dateDisplay').textContent = dateStr;
            d.getElementById('footerDate').textContent = dateStr;

            // Update SVG map title
            const svgText = d.querySelector('.map-svg svg text:first-child');
            if (svgText) {
                svgText.textContent = `${data.WHs_ID} — ${data.Racking_Type} RACK LAYOUT`;
            }

            const rack7Rect = d.querySelector('.map-svg svg rect[fill="rgba(192,57,43,0.12)"]');
            if (rack7Rect) {
                rack7Rect.setAttribute('stroke', '#c0392b');
            }
        }
