async function sbAutoMap(f, data) {
  const msg = PLQ('#sbMsg'), say = t => { if (msg && PLQ('#view-locsign.active')) msg.textContent = t; }; if (!sbMc.ok || rkS.maps[data.Location_Code]) { if (rkS.maps[data.Location_Code]) say(''); return; }
  const e = sbMcFind(data); if (!e) { say('🗺 No picture named “' + data.Location_Code + '” in the map folder.'); return; }
  try { let u = sbMc.cache.get(e.name); if (!u) { say('🗺 Loading ' + e.name + '…'); u = await sbMcFetch(e); sbMc.cache.set(e.name, u); }
    if (f.isConnected && f._code === data.Location_Code && !rkS.maps[data.Location_Code]) { const d2 = Object.assign({}, data, { Map_Image: u }); sbFill(f.contentWindow.document, d2); say('🗺 Map: ' + e.name); }
  } catch (err) { say('🗺 Could not load ' + e.name + ': ' + (err.message || err)); }
}
function sbMcOpen() {
  document.querySelectorAll('#sbMcModal').forEach(x => x.remove()); const cfg = sbMcCfg(), has = !!rkLS(SB_MCFG_KEY, null), hasFs = typeof window.showDirectoryPicker === 'function';
  const m = document.createElement('div'); m.id = 'sbMcModal'; m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:100005;display:flex;align-items:center;justify-content:center;padding:20px;';
  m.innerHTML = `<div class="card" style="max-width:680px;width:100%;max-height:92vh;overflow:auto;margin:0"><div class="card-header"><div class="card-title">🔗 Map pictures folder</div><button type="button" class="ghost small" data-x="1">✖ Close</button></div>
    <div class="card-desc">The signboard picks its map picture <strong>by file name</strong>: a file called <code>MAQ-4-4-1-1.png</code> (or .jpg, .pdf …) is used for location <code>MAQ-4-4-1-1</code>. A picture you choose by hand for one location still wins.</div>
    <div class="form-group"><label>Where is the folder?</label><div style="display:flex;gap:18px;flex-wrap:wrap"><label class="text-sm" style="display:inline-flex;gap:5px;align-items:center;margin:0"><input type="radio" name="sbMcMode" value="sp" ${cfg.mode !== 'local' ? 'checked' : ''} style="width:auto;margin:0"> ☁ SharePoint / OneDrive</label><label class="text-sm" style="display:inline-flex;gap:5px;align-items:center;margin:0"><input type="radio" name="sbMcMode" value="local" ${cfg.mode === 'local' ? 'checked' : ''} style="width:auto;margin:0"> 📁 A folder on this computer</label></div></div>
    <div data-pane="sp"><div class="form-group"><label>Folder link <span class="hint">or its path inside the connected site’s Documents library</span></label><input type="text" id="sbMcVal" value="${plEsc(cfg.mode === 'local' ? SB_MC_DEF.value : cfg.value)}" placeholder="https://…sharepoint.com/…/Maps   or   Warehouse Location Signboard_Print/Maps"></div>
      <div class="text-sm" style="color:var(--gray-600)">Easiest: in OneDrive / SharePoint open the <strong>Maps</strong> folder → <strong>Share → Copy link</strong> and paste it above. A path such as <code>Warehouse Location Signboard_Print/Maps</code> works when the folder is in the Documents library of the site this app is connected to.</div></div>
    <div data-pane="local" style="display:none"><div class="text-sm" style="color:var(--gray-600);margin-bottom:8px">Pick the <strong>Maps</strong> folder (the OneDrive-synced copy on this computer works). The browser will ask once for permission to read it; after a restart you may have to click <em>Refresh</em> to allow it again. ${hasFs ? '' : '<strong style="color:#b45309">This browser cannot pick folders — use Chrome or Edge, or the SharePoint option.</strong>'}</div><div class="btn-row"><button type="button" class="secondary small" id="sbMcPick" ${hasFs ? '' : 'disabled'}>📁 Choose folder…</button><span class="text-sm" id="sbMcPicked"></span></div></div>
    <div id="sbMcRes" class="text-sm" style="margin:10px 0;min-height:20px"></div>
    <div class="btn-row"><button type="button" class="success" id="sbMcGo">🔗 Connect &amp; test</button><button type="button" class="ghost small" data-x="1">Close</button></div></div>`;
  document.body.appendChild(m); const q = sel => m.querySelector(sel), mode = () => (q('input[name=sbMcMode]:checked') || {}).value;
  const pane = () => { m.querySelectorAll('[data-pane]').forEach(p => p.style.display = p.dataset.pane === mode() ? '' : 'none'); }; pane(); m.addEventListener('change', e => { if (e.target.name === 'sbMcMode') pane(); });
  if (has && cfg.mode === 'local') sbMcIdb('readonly', st => st.get('dir')).then(h => { if (h) q('#sbMcPicked').textContent = '✔ ' + h.name; }).catch(() => {});
  const report = () => { const c = sbMcCount(); q('#sbMcRes').innerHTML = sbMc.ok ? `<div style="color:#0a7a0a;font-weight:600">✔ ${plF(sbMc.n)} picture file(s) found — ${plF(c.hit)} of ${plF(c.total)} locations have a matching picture.</div>${c.miss.length ? `<details style="margin-top:4px"><summary>${plF(c.miss.length)} location(s) without a picture</summary><div style="max-height:140px;overflow:auto;color:var(--gray-600)">${plEsc(c.miss.slice(0, 300).join(', '))}${c.miss.length > 300 ? ' …' : ''}</div></details>` : ''}` : `<div style="color:#b91c1c">✘ ${plEsc(sbMc.msg || 'Not connected.')}</div>`; };
  m.addEventListener('click', async e => {
    if (e.target === m || e.target.closest('[data-x]')) { m.remove(); return; }
    if (e.target.closest('#sbMcPick')) { try { const h = await window.showDirectoryPicker({ mode: 'read' }); await sbMcIdb('readwrite', st => st.put(h, 'dir')); q('#sbMcPicked').textContent = '✔ ' + h.name; } catch (x) { if (x && x.name !== 'AbortError') q('#sbMcRes').innerHTML = '<span style="color:#b91c1c">' + plEsc(x.message) + '</span>'; } return; }
    if (e.target.closest('#sbMcGo')) { const md = mode(); if (md === 'sp' && !q('#sbMcVal').value.trim()) { q('#sbMcRes').innerHTML = '<span style="color:#b91c1c">Enter the folder link or path.</span>'; return; }
      if (md === 'local') { const h = await sbMcIdb('readonly', st => st.get('dir')).catch(() => null); if (!h) { q('#sbMcRes').innerHTML = '<span style="color:#b91c1c">Choose the folder first.</span>'; return; } }
      rkLSset(SB_MCFG_KEY, { mode: md, value: md === 'sp' ? q('#sbMcVal').value.trim() : '' }); q('#sbMcRes').textContent = 'Reading the folder…'; await sbMcLoad(true); report(); } });
}
function sbMcInit() {
  const q = PLQ; if (!q('#sbMcBtn') || q('#sbMcBtn').dataset.w) return; q('#sbMcBtn').dataset.w = '1';
  q('#sbMcBtn').addEventListener('click', sbMcOpen); q('#sbMcRef').addEventListener('click', () => sbMcLoad(true));
  q('#sbMcOff').addEventListener('click', () => { if (!confirm('Disconnect the map folder? Pictures you chose by hand are kept.')) return; try { localStorage.removeItem(SB_MCFG_KEY); } catch (e) {} sbMcIdb('readwrite', st => st.delete('dir')).catch(() => {}); sbMc.mode = ''; sbMcReset(); sbMcInfoPaint(); sbRender(); });
  sbMcLoad(false);
}
function rkPrintDoc(doc, title) { npOpenPrint(doc, title); addActivity('export', 'Printed ' + title); }

